-- Validate emails
SELECT * FROM dbo.Users
WHERE REGEXP_LIKE(Email, '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$');

-- Mask digits
SELECT REGEXP_REPLACE(Phone, '\d', '*') AS Masked FROM dbo.Users;

-- Extract the domain (group 2 would need grouping; here occurrence/flags defaults)
SELECT REGEXP_SUBSTR(Email, '@(.+)$', 1, 1, 'c', 1) AS Domain FROM dbo.Users;

-- Split tags into rows
SELECT value FROM REGEXP_SPLIT_TO_TABLE('sql,ai;vector data', '[,;\s]+');
